const PRODUCTS = [
  {id:'fs-shoe-01',name:'Velocity Runner',category:'Кроссовки',label:'NEW DROP',price:1850,image:"data:image/webp;base64,",color:'Black / White',description:'Лёгкая спортивная модель для динамичных тренировок и активного дня.'},
  {id:'fs-shirt-01',name:'Onyx Training Tee',category:'Футболки',label:'BESTSELLER',price:690,image:"data:image/webp;base64,",color:'Onyx Black',description:'Функциональная футболка с лаконичным силуэтом для тренировок.'},
  {id:'fs-bag-01',name:'Aero Gym Duffel',category:'Сумки',label:'EDITOR’S PICK',price:1250,image:"data:image/webp;base64,",color:'Black',description:'Вместительная спортивная сумка для зала, поездок и повседневного использования.'},
  {id:'fs-shorts-01',name:'Core Training Shorts',category:'Шорты',label:'',price:540,image:"data:image/webp;base64,",color:'Black',description:'Лёгкие тренировочные шорты со свободой движения.'},
  {id:'fs-pants-01',name:'Flex Tapered Joggers',category:'Штаны',label:'NEW',price:980,image:"data:image/webp;base64,",color:'Graphite',description:'Зауженные джоггеры для разминки, тренировок и города.'},
  {id:'fs-shirt-02',name:'Performance Compression Tee',category:'Футболки',label:'',price:760,image:"data:image/webp;base64,",color:'Charcoal',description:'Эластичная тренировочная футболка с плотной посадкой.'},
  {id:'fs-bag-02',name:'Transit Crossbody',category:'Сумки',label:'LIMITED',price:820,image:"data:image/webp;base64,",color:'Black',description:'Компактная сумка через плечо для вещей, которые должны быть под рукой.'},
  {id:'fs-accessory-01',name:'Training Essentials Set',category:'Аксессуары',label:'',price:430,image:"data:image/webp;base64,",color:'Black / Purple',description:'Набор аксессуаров для повседневных тренировок.'}
];

// Hero artwork reuses the same embedded product images; no separate image files are required.
const heroShoe = document.querySelector('.hero-shoe img');
const heroShirt = document.querySelector('.hero-shirt img');
if (heroShoe) heroShoe.src = PRODUCTS.find(p => p.id === 'fs-shoe-01').image;
if (heroShirt) heroShirt.src = PRODUCTS.find(p => p.id === 'fs-shirt-01').image;

const $ = (selector, root=document) => root.querySelector(selector);
const money = value => `${new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(value)} TMT`;
let activeCategory = 'Все';
let cart = {};
let toastTimer;

function renderProducts(){
  const query = $('#productSearch').value.trim().toLocaleLowerCase('ru');
  const filtered = PRODUCTS.filter(p => (activeCategory === 'Все' || p.category === activeCategory) && (!query || `${p.name} ${p.category} ${p.color}`.toLocaleLowerCase('ru').includes(query)));
  $('#showingCount').textContent = String(filtered.length).padStart(2,'0');
  $('#productGrid').innerHTML = filtered.length ? filtered.map((p,index)=>`
    <article class="product-card" style="animation-delay:${index*35}ms">
      <div class="product-image">
        ${p.label ? `<span class="product-tag">${p.label}</span>` : ''}
        <img src="${p.image}" alt="${p.name}" loading="${index>3?'lazy':'eager'}">
        <button class="quick-add" data-add="${p.id}" aria-label="Добавить ${p.name} в корзину">+</button>
      </div>
      <div class="product-info"><span class="product-category">${p.category}</span><h3 class="product-name">${p.name}</h3><div class="product-bottom"><span class="product-price">${money(p.price)}</span><span class="product-color">${p.color}</span></div></div>
    </article>`).join('') : '<div class="empty-state">Ничего не найдено. Попробуйте изменить запрос.</div>';
}

function cartEntries(){return Object.entries(cart).map(([id,quantity])=>({product:PRODUCTS.find(p=>p.id===id),quantity})).filter(x=>x.product)}
function cartCount(){return Object.values(cart).reduce((sum,n)=>sum+n,0)}
function cartTotal(){return cartEntries().reduce((sum,x)=>sum+x.product.price*x.quantity,0)}
function renderCart(){
  const entries=cartEntries();
  $('#cartCount').textContent=cartCount();
  $('#drawerCount').textContent=`(${cartCount()})`;
  $('#cartTotal').textContent=money(cartTotal());
  $('#checkoutTotal').textContent=money(cartTotal());
  $('#cartItems').innerHTML=entries.length?entries.map(({product:p,quantity})=>`<div class="cart-row"><img src="${p.image}" alt=""><div><h3>${p.name}</h3><small>${p.category} · ${money(p.price)}</small><div class="qty-controls"><button data-qty="${p.id}" data-delta="-1" aria-label="Уменьшить количество">−</button><span>${quantity}</span><button data-qty="${p.id}" data-delta="1" aria-label="Увеличить количество">+</button></div></div><div><strong>${money(p.price*quantity)}</strong><button class="remove-item" data-remove="${p.id}" aria-label="Удалить товар">×</button></div></div>`).join(''):'<div class="cart-empty">Корзина пока пуста.<br>Самое время выбрать экипировку.</div>';
  $('#checkoutStart').disabled=!entries.length;
  $('#checkoutStart').style.opacity=entries.length?'1':'.45';
}
function showToast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200)}
function openCart(){renderCart();$('#cartDrawer').classList.add('open');$('#cartDrawer').setAttribute('aria-hidden','false');$('#overlay').classList.add('visible');document.body.classList.add('locked')}
function closeCart(){ $('#cartDrawer').classList.remove('open');$('#cartDrawer').setAttribute('aria-hidden','true');if(!$('#checkoutModal').classList.contains('open')){$('#overlay').classList.remove('visible');document.body.classList.remove('locked')} }
function openCheckout(){if(!cartCount())return;closeCart();$('#checkoutModal').classList.add('open');$('#checkoutModal').setAttribute('aria-hidden','false');$('#overlay').classList.add('visible');document.body.classList.add('locked');$('#formMessage').textContent='';$('#formMessage').className='form-message';$('#checkoutTotal').textContent=money(cartTotal());setTimeout(()=>$('#checkoutForm [name="name"]').focus(),100)}
function closeCheckout(){ $('#checkoutModal').classList.remove('open');$('#checkoutModal').setAttribute('aria-hidden','true');$('#overlay').classList.remove('visible');document.body.classList.remove('locked') }
function syncAddress(){const delivery=$('#deliveryMethod').value==='delivery';$('.address-field').style.display=delivery?'flex':'none';$('.address-field input').required=delivery}

$('#productGrid').addEventListener('click',event=>{const button=event.target.closest('[data-add]');if(!button)return;const id=button.dataset.add;cart[id]=Math.min((cart[id]||0)+1,10);renderCart();showToast('Добавлено в корзину');});
$('#categoryTabs').addEventListener('click',event=>{const button=event.target.closest('[data-category]');if(!button)return;activeCategory=button.dataset.category;$('#categoryTabs').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===button));renderProducts();});
$('#productSearch').addEventListener('input',renderProducts);
document.querySelectorAll('[data-filter-link]').forEach(link=>link.addEventListener('click',()=>{const target=link.dataset.filterLink;activeCategory=target;$('#categoryTabs').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.category===target));renderProducts()}));
$('#searchToggle').addEventListener('click',()=>{$('#productSearch').focus();$('#catalog').scrollIntoView({behavior:'smooth'})});
$('#openCart').addEventListener('click',openCart);$('#closeCart').addEventListener('click',closeCart);$('#checkoutStart').addEventListener('click',openCheckout);$('#closeCheckout').addEventListener('click',closeCheckout);
$('#overlay').addEventListener('click',()=>{closeCart();closeCheckout()});
$('#cartItems').addEventListener('click',event=>{const qty=event.target.closest('[data-qty]');const remove=event.target.closest('[data-remove]');if(qty){const id=qty.dataset.qty;cart[id]=Math.max(0,Math.min(10,(cart[id]||0)+Number(qty.dataset.delta)));if(!cart[id])delete cart[id];renderCart()}if(remove){delete cart[remove.dataset.remove];renderCart()}});
$('#deliveryMethod').addEventListener('change',syncAddress);
$('#checkoutForm').addEventListener('submit',async event=>{
  event.preventDefault();
  const form=event.currentTarget;
  if(!form.reportValidity())return;
  if(!cartCount()){showToast('Корзина пуста');return}
  const button=$('#submitOrder');const message=$('#formMessage');button.disabled=true;button.innerHTML='Отправляем…';message.textContent='';message.className='form-message';
  const data=new FormData(form);
  const payload={name:data.get('name'),phone:data.get('phone'),city:data.get('city'),method:data.get('method'),address:data.get('address'),comment:data.get('comment'),website:data.get('website'),consent:data.get('consent')==='on',items:cartEntries().map(({product,quantity})=>({id:product.id,quantity}))};
  try{
    const response=await fetch('/api/demo-order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
    const result=await response.json().catch(()=>({}));
    if(!response.ok)throw new Error(result.error||'Не удалось отправить заказ. Попробуйте ещё раз.');
    message.textContent=`Готово! Заказ ${result.order_number} отправлен в Telegram.`;message.className='form-message';
    button.innerHTML='Заказ отправлен ✓';
    cart={};renderCart();
    setTimeout(()=>{form.reset();syncAddress();closeCheckout();button.disabled=false;button.innerHTML='Отправить демо-заказ <span>↗</span>';showToast('Демо-заказ успешно отправлен')},1800);
  }catch(error){message.textContent=error.message;message.className='form-message error';button.disabled=false;button.innerHTML='Повторить отправку <span>↗</span>'}
});

document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeCart();closeCheckout()}});
renderProducts();renderCart();syncAddress();
